diff --git a/firmware/src/runner/button_latch.c b/firmware/src/runner/button_latch.c
new file mode 100644
index 0000000..a5ca80b
--- /dev/null
+++ b/firmware/src/runner/button_latch.c
@@ -0,0 +1,42 @@
+#include "runner/button_latch.h"
+
+void button_latch_init(ButtonLatch *l, uint32_t settle_ms) {
+  l->pending = 0;
+  l->first_ms = 0;
+  l->settle_ms = settle_ms;
+  l->candidate_since_ms = 0;
+  l->has_sample = false;
+  l->stable_down = false;
+  l->candidate_down = false;
+}
+
+void button_latch_sample(ButtonLatch *l, bool down, uint32_t now_ms) {
+  if (!l->has_sample) {
+    l->has_sample = true;
+    l->stable_down = down;
+    l->candidate_down = down;
+    return;
+  }
+  if (down == l->stable_down) {
+    l->candidate_down = down;
+    return;
+  }
+  if (l->candidate_down != down) {
+    l->candidate_down = down;
+    l->candidate_since_ms = now_ms;
+  }
+  if ((uint32_t)(now_ms - l->candidate_since_ms) < l->settle_ms) return;
+  l->stable_down = down;
+  if (!down) return;
+  if (l->pending == 0) l->first_ms = l->candidate_since_ms;
+  __atomic_fetch_add(&l->pending, 1, __ATOMIC_RELEASE);
+}
+
+uint32_t button_latch_pending(const ButtonLatch *l) { return l->pending; }
+
+bool button_latch_take(ButtonLatch *l, uint32_t *began_ms) {
+  uint32_t taken = __atomic_exchange_n(&l->pending, 0, __ATOMIC_ACQUIRE);
+  if (taken == 0) return false;
+  if (began_ms) *began_ms = l->first_ms;
+  return true;
+}
diff --git a/firmware/src/runner/button_latch.h b/firmware/src/runner/button_latch.h
new file mode 100644
index 0000000..dad8c2e
--- /dev/null
+++ b/firmware/src/runner/button_latch.h
@@ -0,0 +1,46 @@
+#ifndef RUNNER_BUTTON_LATCH_H
+#define RUNNER_BUTTON_LATCH_H
+
+#include <stdbool.h>
+#include <stddef.h>
+#include <stdint.h>
+
+#ifdef __cplusplus
+extern "C" {
+#endif
+
+/* Remembers button presses that arrive while the main loop is busy, so a hack
+ * with a long draw step cannot make a press vanish. A background task feeds it
+ * samples of the button line every few milliseconds; the main loop takes the
+ * presses. The line only counts as changed once it has held its new level for
+ * the settle time, so bounce on press or release cannot produce extra presses. */
+typedef struct {
+  volatile uint32_t pending;
+  volatile uint32_t first_ms;
+  uint32_t settle_ms;
+  uint32_t candidate_since_ms;
+  bool has_sample;
+  bool stable_down;
+  bool candidate_down;
+} ButtonLatch;
+
+void button_latch_init(ButtonLatch *l, uint32_t settle_ms);
+
+/* One reading of the line (down is true while the button is pressed) taken at
+ * now_ms. The first sample only sets the starting state, so a button held at
+ * boot is not a press. */
+void button_latch_sample(ButtonLatch *l, bool down, uint32_t now_ms);
+
+/* Presses confirmed and not yet taken. */
+uint32_t button_latch_pending(const ButtonLatch *l);
+
+/* True if any press is pending. All pending presses are consumed at once, since
+ * extra presses during a long step are almost always retries. When began_ms is
+ * not NULL it receives the time the earliest press taken began. */
+bool button_latch_take(ButtonLatch *l, uint32_t *began_ms);
+
+#ifdef __cplusplus
+}
+#endif
+
+#endif
diff --git a/firmware/src/x11shim/helpers.c b/firmware/src/x11shim/helpers.c
index b9a5e72..7448fd9 100644
--- a/firmware/src/x11shim/helpers.c
+++ b/firmware/src/x11shim/helpers.c
@@ -1,5 +1,6 @@
 /* Shim versions of the few xscreensaver utils helpers that hacks call.
  * Written for this project; not derived from xscreensaver's utils. */
+#include <math.h>
 #include <stdlib.h>

 #include "colors.h"
@@ -37,3 +38,75 @@ void make_random_colormap(Screen *screen, Visual *visual, Colormap cmap,
     colors[i].pixel = rgb565_from16(colors[i].red, colors[i].green, colors[i].blue);
   }
 }
+
+static void set_colour(XColor *c, double h, double s, double v) {
+  h = fmod(h, 360.0);
+  if (h < 0) h += 360.0;
+  hsv_to_rgb((int)h, s, v, &c->red, &c->green, &c->blue);
+  c->flags = DoRed | DoGreen | DoBlue;
+  c->pixel = rgb565_from16(c->red, c->green, c->blue);
+}
+
+void make_uniform_colormap(Screen *screen, Visual *visual, Colormap cmap,
+                           XColor *colors, int *ncolorsP, Bool allocate_p,
+                           Bool *writable_pP, Bool verbose_p) {
+  (void)screen;
+  (void)visual;
+  (void)cmap;
+  (void)allocate_p;
+  (void)verbose_p;
+  if (writable_pP) *writable_pP = False;
+  double base = frand_unit() * 360.0;
+  for (int i = 0; i < *ncolorsP; i++)
+    set_colour(&colors[i], base + i * 360.0 / *ncolorsP, 1.0, 1.0);
+}
+
+/* Three anchor colours, one per third of the hue wheel so the loop always
+ * goes all the way round, blended forward from each anchor to the next and
+ * from the last back to the first. */
+#define SMOOTH_ANCHORS 3
+
+void make_smooth_colormap(Screen *screen, Visual *visual, Colormap cmap,
+                          XColor *colors, int *ncolorsP, Bool allocate_p,
+                          Bool *writable_pP, Bool verbose_p) {
+  (void)screen;
+  (void)visual;
+  (void)cmap;
+  (void)allocate_p;
+  (void)verbose_p;
+  if (writable_pP) *writable_pP = False;
+  double h[SMOOTH_ANCHORS], s[SMOOTH_ANCHORS], v[SMOOTH_ANCHORS];
+  for (int k = 0; k < SMOOTH_ANCHORS; k++) {
+    h[k] = (k + frand_unit()) * 360.0 / SMOOTH_ANCHORS;
+    s[k] = 0.6 + frand_unit() * 0.4;
+    v[k] = 0.75 + frand_unit() * 0.25;
+  }
+  for (int i = 0; i < *ncolorsP; i++) {
+    double t = (double)i * SMOOTH_ANCHORS / *ncolorsP;
+    int k = (int)t, next = (k + 1) % SMOOTH_ANCHORS;
+    double f = t - k;
+    double dh = fmod(h[next] - h[k] + 360.0, 360.0);
+    set_colour(&colors[i], h[k] + dh * f, s[k] + (s[next] - s[k]) * f,
+               v[k] + (v[next] - v[k]) * f);
+  }
+}
+
+void free_colors(Screen *screen, Colormap cmap, XColor *colors, int ncolors) {
+  (void)screen;
+  (void)cmap;
+  (void)colors;
+  (void)ncolors;
+}
+
+#ifdef ARDUINO
+#include <signal.h>
+
+/* The ESP32 C library has no signal(), but flame.c calls
+ * signal(SIGFPE, SIG_IGN). The Xtensa FPU never traps, so ignoring the signal
+ * is already what happens. */
+_sig_func_ptr signal(int sig, _sig_func_ptr handler) {
+  (void)sig;
+  (void)handler;
+  return SIG_DFL;
+}
+#endif
