+bool button_latch_take(ButtonLatch *l, uint32_t *began_ms) {
+  uint32_t taken = __atomic_exchange_n(&l->pending, 0, __ATOMIC_ACQUIRE);
+  if (taken == 0) return false;
+  if (began_ms) *began_ms = l->first_ms;
+  return true;
