/* Samples the button every POLL_MS from `from` up to (not including) `to`. */
static void hold(bool down, uint32_t from, uint32_t to) {
  for (uint32_t t = from; (uint32_t)(to - t) != 0 && (uint32_t)(to - t) < 0x80000000u;
       t += POLL_MS)
    button_latch_sample(&latch, down, t);
}

void setUp(void) {
  button_latch_init(&latch, 30);
  button_latch_sample(&latch, false, 0);
}
void tearDown(void) {}

void test_a_button_left_alone_gives_nothing_to_take(void) {
  hold(false, 5, 1000);
  TEST_ASSERT_FALSE(button_latch_take(&latch, NULL));
}

void test_a_click_is_one_press_taken_once(void) {
  hold(false, 5, 100);
  hold(true, 100, 250);
  hold(false, 250, 400);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
  TEST_ASSERT_TRUE(button_latch_take(&latch, NULL));
  TEST_ASSERT_FALSE(button_latch_take(&latch, NULL));
}

void test_a_press_only_counts_once_it_has_settled(void) {
  hold(true, 100, 125);
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&latch));
  hold(true, 125, 135);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
}

void test_a_long_press_is_still_one_press(void) {
  hold(true, 100, 5000);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
}

void test_a_glitch_shorter_than_the_settle_time_is_ignored(void) {
  hold(true, 100, 120);
  hold(false, 120, 400);
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&latch));
}

void test_an_old_glitch_does_not_shorten_the_settle_time_of_a_later_press(void) {
  hold(true, 100, 120);
  hold(false, 120, 400);
  hold(true, 400, 425);
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&latch));
  hold(true, 425, 435);
  uint32_t began = 0;
  TEST_ASSERT_TRUE(button_latch_take(&latch, &began));
  TEST_ASSERT_EQUAL_UINT32(400, began);
}

void test_bounce_on_press_is_one_press(void) {
  hold(true, 100, 105);
  hold(false, 105, 110);
  hold(true, 110, 115);
  hold(false, 115, 120);
  hold(true, 120, 300);
  hold(false, 300, 400);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
}

void test_bounce_on_release_is_not_a_second_press(void) {
  hold(true, 100, 250);
  TEST_ASSERT_TRUE(button_latch_take(&latch, NULL));
  hold(false, 250, 255);
  hold(true, 255, 260);
  hold(false, 260, 265);
  hold(true, 265, 270);
  hold(false, 270, 500);
  TEST_ASSERT_FALSE(button_latch_take(&latch, NULL));
}

void test_two_separate_clicks_are_two_presses(void) {
  hold(true, 100, 250);
  hold(false, 250, 400);
  hold(true, 400, 550);
  hold(false, 550, 700);
  TEST_ASSERT_EQUAL_UINT32(2, button_latch_pending(&latch));
}

void test_taking_collapses_several_pending_presses_into_one_event(void) {
  hold(true, 100, 250);
  hold(false, 250, 400);
  hold(true, 400, 550);
  hold(false, 550, 700);
  TEST_ASSERT_TRUE(button_latch_take(&latch, NULL));
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&latch));
  TEST_ASSERT_FALSE(button_latch_take(&latch, NULL));
}

void test_a_press_after_a_take_is_a_new_event(void) {
  hold(true, 100, 250);
  TEST_ASSERT_TRUE(button_latch_take(&latch, NULL));
  hold(false, 250, 400);
  hold(true, 400, 550);
  TEST_ASSERT_TRUE(button_latch_take(&latch, NULL));
}

void test_take_reports_when_the_press_began(void) {
  hold(false, 5, 1000);
  hold(true, 1000, 1200);
  uint32_t began = 0;
  TEST_ASSERT_TRUE(button_latch_take(&latch, &began));
  TEST_ASSERT_EQUAL_UINT32(1000, began);
}

void test_a_button_held_at_start_is_not_a_press(void) {
  ButtonLatch held_at_boot;
  button_latch_init(&held_at_boot, 30);
  for (uint32_t t = 0; t < 500; t += POLL_MS)
    button_latch_sample(&held_at_boot, true, t);
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&held_at_boot));
  for (uint32_t t = 500; t < 700; t += POLL_MS)
    button_latch_sample(&held_at_boot, false, t);
  for (uint32_t t = 700; t < 900; t += POLL_MS)
    button_latch_sample(&held_at_boot, true, t);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&held_at_boot));
}

void test_the_settle_time_survives_the_millisecond_counter_wrapping(void) {
  hold(false, 5, 0xFFFFFF00u);
  hold(false, 0xFFFFFF00u, 0xFFFFFFF0u);
  hold(true, 0xFFFFFFF0u, 0x00000050u);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
}

int main(void) {
  UNITY_BEGIN();
  RUN_TEST(test_a_button_left_alone_gives_nothing_to_take);
  RUN_TEST(test_a_click_is_one_press_taken_once);
  RUN_TEST(test_a_press_only_counts_once_it_has_settled);
  RUN_TEST(test_a_long_press_is_still_one_press);
  RUN_TEST(test_a_glitch_shorter_than_the_settle_time_is_ignored);
  RUN_TEST(test_an_old_glitch_does_not_shorten_the_settle_time_of_a_later_press);
  RUN_TEST(test_bounce_on_press_is_one_press);
  RUN_TEST(test_bounce_on_release_is_not_a_second_press);
  RUN_TEST(test_two_separate_clicks_are_two_presses);
  RUN_TEST(test_taking_collapses_several_pending_presses_into_one_event);
  RUN_TEST(test_a_press_after_a_take_is_a_new_event);
  RUN_TEST(test_take_reports_when_the_press_began);
  RUN_TEST(test_a_button_held_at_start_is_not_a_press);
  RUN_TEST(test_the_settle_time_survives_the_millisecond_counter_wrapping);
  return UNITY_END();
}
#include "core/canvas.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

/* The ESP32 has a 32-bit long; clip arithmetic needs 64 bits to be safe. */
typedef int64_t wide_t;

int canvas_init(Canvas *c, int w, int h, void *(*alloc)(size_t)) {
  c->w = w;
  c->h = h;
  c->px = (uint16_t *)alloc((size_t)w * (size_t)h * sizeof(uint16_t));
  if (!c->px) return -1;
  memset(c->px, 0, (size_t)w * (size_t)h * sizeof(uint16_t));
  return 0;
}

void canvas_free(Canvas *c) {
  free(c->px);
  c->px = NULL;
}

uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
  return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

uint16_t rgb565_from16(uint16_t r, uint16_t g, uint16_t b) {
  return rgb565((uint8_t)(r >> 8), (uint8_t)(g >> 8), (uint8_t)(b >> 8));
}

void canvas_clear(Canvas *c, uint16_t color) {
  for (int i = 0, n = c->w * c->h; i < n; i++) c->px[i] = color;
}

void canvas_point(Canvas *c, int x, int y, uint16_t color) {
  if (x < 0 || y < 0 || x >= c->w || y >= c->h) return;
  c->px[(size_t)y * c->w + x] = color;
}

static void hspan(Canvas *c, wide_t x0, wide_t x1, wide_t y, uint16_t color) {
  if (y < 0 || y >= c->h || x1 < 0 || x0 >= c->w) return;
  if (x0 < 0) x0 = 0;
  if (x1 >= c->w) x1 = c->w - 1;
  uint16_t *row = c->px + (size_t)y * c->w;
  for (int x = (int)x0, last = (int)x1; x <= last; x++) row[x] = color;
}

void canvas_fill_rect(Canvas *c, int x, int y, int w, int h, uint16_t color) {
  if (w <= 0 || h <= 0) return;
  wide_t x1 = (wide_t)x + w - 1, y1 = (wide_t)y + h - 1;
  wide_t y0 = y < 0 ? 0 : y;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) hspan(c, x, x1, yy, color);
}

/* Liang-Barsky clip of the segment to [0,w-1]x[0,h-1]; false if outside. */
static int clip_line(const Canvas *c, double *x0, double *y0, double *x1,
                     double *y1) {
  double dx = *x1 - *x0, dy = *y1 - *y0, t0 = 0, t1 = 1;
  double p[4] = {-dx, dx, -dy, dy};
  double q[4] = {*x0, (c->w - 1) - *x0, *y0, (c->h - 1) - *y0};
  for (int i = 0; i < 4; i++) {
    if (p[i] == 0) {
      if (q[i] < 0) return 0;
    } else {
      double t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return 0;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return 0;
        if (t < t1) t1 = t;
      }
    }
  }
  double ax = *x0, ay = *y0;
  *x0 = ax + t0 * dx;
  *y0 = ay + t0 * dy;
  *x1 = ax + t1 * dx;
  *y1 = ay + t1 * dy;
  return 1;
}

void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color) {
  double ax = x0, ay = y0, bx = x1, by = y1;
  int clipped = x0 < 0 || y0 < 0 || x0 >= c->w || y0 >= c->h || x1 < 0 ||
                y1 < 0 || x1 >= c->w || y1 >= c->h;
  if (clipped) {
    if (!clip_line(c, &ax, &ay, &bx, &by)) return;
    ax = floor(ax + 0.5);
    ay = floor(ay + 0.5);
    bx = floor(bx + 0.5);
    by = floor(by + 0.5);
  }
  int ix0 = (int)ax, iy0 = (int)ay, ix1 = (int)bx, iy1 = (int)by;
  int dx = abs(ix1 - ix0), sx = ix0 < ix1 ? 1 : -1;
  int dy = -abs(iy1 - iy0), sy = iy0 < iy1 ? 1 : -1;
  int err = dx + dy;
  for (;;) {
    canvas_point(c, ix0, iy0, color);
    if (ix0 == ix1 && iy0 == iy1) break;
    int e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      ix0 += sx;
    }
    if (e2 <= dx) {
      err += dx;
      iy0 += sy;
    }
  }
}

void canvas_fill_ellipse(Canvas *c, int x, int y, int w, int h,
                         uint16_t color) {
  if (w <= 0 || h <= 0) return;
  double cx = x + (w - 1) / 2.0, cy = y + (h - 1) / 2.0;
  double rx = w / 2.0, ry = h / 2.0;
  wide_t y0 = y < 0 ? 0 : y, y1 = (wide_t)y + h - 1;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) {
    double ny = (yy - cy) / ry;
    double t = 1.0 - ny * ny;
    if (t < 0) continue;
    double half = rx * sqrt(t);
    wide_t xa = (wide_t)ceil(cx - half), xb = (wide_t)floor(cx + half);
    if (xb < xa) continue;
    hspan(c, xa, xb, yy, color);
  }
}

/* Insertion sort is quadratic, and with software doubles a 1000-point Pedal
 * picture spent seconds in it. Past a handful of crossings qsort wins. */
#define SORT_INSERTION_MAX 16

static int compare_doubles(const void *a, const void *b) {
  double x = *(const double *)a, y = *(const double *)b;
  return (x > y) - (x < y);
}

void canvas_fill_polygon(Canvas *c, const int *xy, int n, uint16_t color) {
  if (n < 3) return;
  /* An edge crosses a scanline at most once, so n slots always suffice. The
   * heap is only used for big polygons, to keep the task stack small. */
  double stack_xs[64];
  double *xs = stack_xs;
  if (n > 64) {
    xs = (double *)malloc((size_t)n * sizeof(double));
    if (!xs) return;
  }
  wide_t ymin = xy[1], ymax = xy[1];
  for (int i = 1; i < n; i++) {
    if (xy[2 * i + 1] < ymin) ymin = xy[2 * i + 1];
    if (xy[2 * i + 1] > ymax) ymax = xy[2 * i + 1];
  }
  if (ymin < 0) ymin = 0;
  if (ymax >= c->h) ymax = c->h - 1;
  for (wide_t yy = ymin; yy <= ymax; yy++) {
    int nx = 0;
    double sy = yy + 0.5;
    for (int i = 0, j = n - 1; i < n; j = i++) {
      double yi = xy[2 * i + 1], yj = xy[2 * j + 1];
      if ((yi <= sy && yj > sy) || (yj <= sy && yi > sy)) {
        double t = (sy - yi) / (yj - yi);
        xs[nx++] = xy[2 * i] + t * (xy[2 * j] - xy[2 * i]);
      }
    }
    if (nx > SORT_INSERTION_MAX) {
      qsort(xs, (size_t)nx, sizeof(double), compare_doubles);
    } else {
      for (int a = 1; a < nx; a++)
        for (int b = a; b > 0 && xs[b - 1] > xs[b]; b--) {
          double tmp = xs[b];
          xs[b] = xs[b - 1];
          xs[b - 1] = tmp;
        }
    }
    for (int k = 0; k + 1 < nx; k += 2)
      hspan(c, (wide_t)ceil(xs[k] - 0.5), (wide_t)ceil(xs[k + 1] - 0.5) - 1, yy,
            color);
  }
  if (xs != stack_xs) free(xs);
}

static unsigned long
coral_draw (Display *dpy, Window window, void *closure)
{
  struct state *st = (struct state *) closure;

  if (st->eraser || st->done)
    {
      st->done = 0;
      st->eraser = erase_window (st->dpy, st->window, st->eraser);
      return st->delay2;
    }

  if (st->reset)
    init_coral(st);
  st->reset = st->done = coral(st);

  return (st->reset
          ? (st->delay * 1000000)
          : st->delay2);
}

static void
coral_reshape (Display *dpy, Window window, void *closure, 
                 unsigned int w, unsigned int h)
{
  struct state *st = (struct state *) closure;
  init_coral(st);
}

static Bool
coral_event (Display *dpy, Window window, void *closure, XEvent *event)
{
  struct state *st = (struct state *) closure;
  if (screenhack_event_helper (dpy, window, event))
    {
      st->reset = 1;
      return True;
    }
  return False;
}

static void
coral_free (Display *dpy, Window window, void *closure)
{
  struct state *st = (struct state *) closure;
  free (st->pointbuf);
  XFreeGC (dpy, st->draw_gc);
  XFreeGC (dpy, st->erase_gc);
  if (st->walkers) free (st->walkers);
  if (st->board) free (st->board);
  free (st);
}

