     3	void button_latch_init(ButtonLatch *l, uint32_t settle_ms) {
     4	  l->pending = 0;
     5	  l->first_ms = 0;
     6	  l->settle_ms = settle_ms;
     7	  l->candidate_since_ms = 0;
     8	  l->has_sample = false;
     9	  l->stable_down = false;
    10	  l->candidate_down = false;
    11	}
    12	
    13	void button_latch_sample(ButtonLatch *l, bool down, uint32_t now_ms) {
    14	  if (!l->has_sample) {
    15	    l->has_sample = true;
    16	    l->stable_down = down;
    17	    l->candidate_down = down;
    18	    return;
    19	  }
    20	  if (down == l->stable_down) {
    21	    l->candidate_down = down;
    22	    return;
    23	  }
    24	  if (l->candidate_down != down) {
    25	    l->candidate_down = down;
    26	    l->candidate_since_ms = now_ms;
    27	  }
    28	  if ((uint32_t)(now_ms - l->candidate_since_ms) < l->settle_ms) return;
    29	  l->stable_down = down;
    30	  if (!down) return;
    31	  if (l->pending == 0) l->first_ms = l->candidate_since_ms;
    32	  __atomic_fetch_add(&l->pending, 1, __ATOMIC_RELEASE);
    33	}
    34	
    35	uint32_t button_latch_pending(const ButtonLatch *l) { return l->pending; }
    36	
    37	bool button_latch_take(ButtonLatch *l, uint32_t *began_ms) {
    38	  uint32_t taken = __atomic_exchange_n(&l->pending, 0, __ATOMIC_ACQUIRE);
    39	  if (taken == 0) return false;
    40	  if (began_ms) *began_ms = l->first_ms;
    41	  return true;
    42	}
